const oldFile = {
  name: "greeting.ts",
  contents: "export function greet(name: string) {\n  return `Hello, ${name}`;\n}\n",
};
const newFile = {
  name: "greeting.ts",
  contents:
    'export function greet(name: string = "world") {\n  const greeting = `Welcome, ${name}!`;\n  return greeting;\n}\n',
};
export { oldFile, newFile };

import { useState } from "react";
import { DiffView } from "@/registry/erbium/blocks/diff-view";
import type { DiffViewOptions } from "@/registry/erbium/blocks/diff-view";
import { ToggleGroup, ToggleGroupItem } from "@/registry/erbium/ui/toggle-group";
import { oldFile, newFile } from "../examples/files";

export default function Example() {
  const [highlight, setHighlight] = useState<DiffViewOptions["lineDiffType"]>("word-alt");
  return (
    <div className="grid w-full max-w-4xl gap-4">
      <ToggleGroup
        aria-label="Inline change highlighting"
        value={[highlight ?? "word-alt"]}
        onValueChange={(values) => {
          const value = values[0];
          if (value === "word-alt" || value === "char" || value === "none") setHighlight(value);
        }}
        size="sm"
        variant="outline"
      >
        <ToggleGroupItem value="word-alt">Words</ToggleGroupItem>
        <ToggleGroupItem value="char">Characters</ToggleGroupItem>
        <ToggleGroupItem value="none">Lines only</ToggleGroupItem>
      </ToggleGroup>
      <DiffView oldFile={oldFile} newFile={newFile} options={{ lineDiffType: highlight }} />
      <DiffView
        oldFile={oldFile}
        newFile={newFile}
        options={{ diffStyle: "unified", diffIndicators: "bars", disableLineNumbers: true }}
      />
    </div>
  );
}
